class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        ans = 0
        two_k = 2 * k

        # For Manhattan distance:
        # |x| + |y| = max over sx, sy in {-1, 1} of sx * x + sy * y
        for sx in (1, -1):
            for sy in (1, -1):
                pref = 0
                neg = 0

                for ch in s:
                    if ch == 'N':
                        val = sy
                    elif ch == 'S':
                        val = -sy
                    elif ch == 'E':
                        val = sx
                    else:  # 'W'
                        val = -sx

                    pref += val
                    if val < 0:
                        neg += 1

                    # Flip up to k negative contributions in this prefix to +1.
                    gain = two_k if neg >= k else 2 * neg
                    cand = pref + gain

                    if cand > ans:
                        ans = cand

        return ans
