from typing import List

class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        take = True

        for r in range(len(grid)):
            if r % 2 == 0:
                cols = range(len(grid[r]))
            else:
                cols = range(len(grid[r]) - 1, -1, -1)

            for c in cols:
                if take:
                    result.append(grid[r][c])
                take = not take

        return result
