from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        offline_until = [0] * numberOfUsers

        def sort_key(event: List[str]):
            return (int(event[1]), 0 if event[0] == "OFFLINE" else 1)

        for event in sorted(events, key=sort_key):
            timestamp = int(event[1])

            if event[0] == "OFFLINE":
                user = int(event[2])
                offline_until[user] = timestamp + 60
            else:
                for token in event[2].split():
                    if token == "ALL":
                        for user in range(numberOfUsers):
                            mentions[user] += 1
                    elif token == "HERE":
                        for user in range(numberOfUsers):
                            if offline_until[user] <= timestamp:
                                mentions[user] += 1
                    else:
                        user = int(token[2:])
                        mentions[user] += 1

        return mentions
