from typing import List

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        base = nums.count(k)
        best_delta = 0

        for value in set(nums):
            if value == k:
                continue

            current = 0
            for num in nums:
                if num == value:
                    current += 1
                elif num == k:
                    current -= 1

                if current < 0:
                    current = 0
                elif current > best_delta:
                    best_delta = current

        return base + best_delta
